commands.shell_command:
$OdinParseErrors = @()
foreach ($OdinPsFile in @('scripts/package.ps1','scripts/verify_installer.ps1')) {
    $OdinTokens = $null
    $OdinErrors = $null
    $null = [System.Management.Automation.Language.Parser]::ParseFile((Join-Path (Get-Location) $OdinPsFile), [ref]$OdinTokens, [ref]$OdinErrors)
    $OdinParseErrors += @($OdinErrors)
}
if ($OdinParseErrors.Count -ne 0) { $OdinParseErrors | Out-String; exit 1 }
Write-Output 'PASS PowerShell AST syntax: package.ps1, verify_installer.ps1'
